INSERT INTO "Category" ("id", "parentId", "name", "perishable", "coldChain", "sort") VALUES ('a0000000-0000-4000-8000-000000000001', NULL, '{"ru": "Фрукты и ягоды", "kk": "Жемістер мен жидектер", "en": "Fruit & berries"}'::jsonb, false, false, 0) ON CONFLICT ("id") DO NOTHING;
